from core.rules import RuleMachine


class SortedReleaseToEmptyBufferRule:
    """Permite mover desde una pila fuente ordenada y baja hacia una pila vacía para liberar casi por completo la fuente."""

    name = "sorted_release_to_empty_buffer"

    def __init__(self, max_source_height=2, max_remaining_height=1, min_empty_stacks=1):
        self.max_source_height = int(max_source_height)
        self.max_remaining_height = int(max_remaining_height)
        self.min_empty_stacks = int(min_empty_stacks)

    def _empty_stacks(self, partial):
        return sum(1 for i in range(partial.S) if partial.h(i) == 0)

    def _is_allowed_type(self, partial, action):
        so = action.so
        sd = action.sd

        hs = partial.h(so)
        if hs == 0:
            return False
        if hs > self.max_source_height:
            return False
        if not partial.is_sorted_stack(so):
            return False
        if partial.h(sd) != 0:
            return False

        remaining = hs - 1
        if remaining > self.max_remaining_height:
            return False

        empty_stacks = self._empty_stacks(partial)
        if empty_stacks < self.min_empty_stacks:
            return False

        if partial.visited is not None:
            nxt = partial.after(so, sd)
            if nxt in partial.visited:
                return False

        return True

    def allowed(self, partial, memory, candidates):
        moves = [a for a in candidates if self._is_allowed_type(partial, a)]
        moves.sort(key=lambda a: self.score(partial, memory, a))
        return moves

    def score(self, partial, memory, action):
        so = action.so
        top_group = partial.g(so)
        remaining = partial.h(so) - 1
        # Prioriza vaciar la fuente; luego dejarla con altura muy baja; después mover grupos grandes.
        return (remaining, -top_group, so, action.sd)


def build_component(problem, **params):
    rule = SortedReleaseToEmptyBufferRule(
        max_source_height=params.get("max_source_height", 2),
        max_remaining_height=params.get("max_remaining_height", 1),
        min_empty_stacks=params.get("min_empty_stacks", 1),
    )
    return RuleMachine(problem, [rule])
